target.css:
:root {
  --paper: #fffdf8;
  --ink: #243038;
  --muted: #6d7778;
  --line: #d9d5c9;
  --wine: #8d3d4c;
  --rose: #f7e8e6;
  --sage: #e8f0e5;
}

.repair-card {
  box-sizing: border-box;
  width: 480px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper);
  color: var(--ink);
}

.ticket-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
}

.ticket-kicker {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 750;
  line-height: 1.05;
}

.status {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--rose);
  color: var(--wine);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
}

.book-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
}

.spine-mark {
  display: grid;
  width: 34px;
  height: 42px;
  place-items: center;
  border-radius: 4px 8px 8px 4px;
  background: var(--wine);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.book-copy {
  min-width: 0;
}

h2 {
  margin: 0 0 2px;
  font-size: 16px;
  font-weight: 750;
  line-height: 1.2;
}

.author {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.3;
}

.condition-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.condition-grid section {
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--sage);
}

h3 {
  margin: 0 0 3px;
  color: var(--wine);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  line-height: 1.2;
  text-transform: uppercase;
}

.condition-grid p {
  margin: 0;
  font-size: 11px;
  line-height: 1.3;
}

.ticket-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
}

.due {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.2;
  white-space: nowrap;
}

.due strong {
  color: var(--ink);
  font-size: 11px;
}

.due span {
  color: var(--wine);
  font-weight: 700;
}

.tag-list {
  display: flex;
  gap: 4px;
  margin: 0 0 0 auto;
  padding: 0;
  list-style: none;
}

.tag {
  padding: 3px 6px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  line-height: 1.2;
  white-space: nowrap;
}

button {
  padding: 7px 9px;
  border: 1px solid var(--wine);
  border-radius: 6px;
  background: var(--wine);
  color: var(--paper);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

